from test_target_priority import test, tests, priority, solo
from test_blessings import setup
ordered=priority+"BuffTap.db.targetBlessingClasses.PRIEST='priority'; BuffTap.db.targetBlessingPriorities.PRIEST={'bok','bow','bol','bos'}; BuffTap.db.buffs.bol=true; BuffTap.db.buffs.bos=true; refresh(); "
group=setup+"UnitIsUnit=function(a,b) return a==b end; UnitExists=function(u) return true end; BuffTap.db.buffs.bok=true; BuffTap.db.buffs.bow=true; BuffTap.db.buffs.bom=true; BuffTap.db.blessingClasses.WARRIOR='priority'; BuffTap.db.groupBlessingPriorities.WARRIOR={'bok','bom','bow'}; refresh(); "
test('Custom target order controls first choice',ordered+"assert(BuffTap.action.key=='bok'); BuffTap.db.targetBlessingPriorities.PRIEST={'bow','bok'}; refresh(); assert(BuffTap.action.key=='bow')")
test('Custom target order reaches third and fourth choices',ordered+"aura('target',20217,'Blessing of Kings'); aura('target',19742,'Blessing of Wisdom'); for _,a in ipairs(auras.target) do a.sourceUnit='other' end; refresh(); assert(BuffTap.action.key=='bol'); aura('target',19977,'Blessing of Light'); auras.target[3].sourceUnit='other'; refresh(); assert(BuffTap.action.key=='bos')")
test('Empty custom list does not silently add a blessing',ordered+"BuffTap.db.targetBlessingPriorities.PRIEST={}; refresh(); assert(not BuffTap.action.quickTarget)")
test('Checked target list entry overrides personal buff toggle',ordered+"BuffTap.db.buffs.bok=false; refresh(); assert(BuffTap.action.key=='bok')")
test('Checked target list entry ignores obsolete target filter',ordered+"BuffTap.db.targetBuffs.bok=false; refresh(); assert(BuffTap.action.key=='bok')")
test('Custom target list skips unlearned entries',ordered+"spells[20217].known=false; BuffTap.bookDirty=true; refresh(); assert(BuffTap.action.key=='bow')")
test('Custom target list maintains own lower priority',ordered+"aura('target',19742,'Blessing of Wisdom'); auras.target[1].sourceUnit='player'; refresh(); assert(not BuffTap.action.quickTarget)")
test('Custom target list obeys fallback toggle',ordered+"BuffTap.db.targetBlessingFallback=false; aura('target',20217,'Blessing of Kings'); auras.target[1].sourceUnit='other'; refresh(); assert(not BuffTap.action.quickTarget)")
test('Group custom order follows missing coverage',group+"assert(BuffTap.action.key=='bok' and BuffTap.action.target=='party1'); aura('party1',20217,'Blessing of Kings'); auras.party1[1].sourceUnit='other'; refresh(); assert(BuffTap.action.key=='bom')")
test('Group unknown ownership blocks priority fallback',group+"aura('party1',20217,'Blessing of Kings'); refresh(); assert(not BuffTap.action or BuffTap.action.target~='party1')")
test('Group own blessing is never replaced by priority',group+"aura('party1',19740,'Blessing of Might'); auras.party1[1].sourceUnit='player'; refresh(); assert(not BuffTap.action or BuffTap.action.target~='party1')")
test('Group explicit player choice overrides class priority',group+"BuffTap:SetBlessingPlayer({unit='party1'},'bow',false); refresh(); assert(BuffTap.action.key=='bow' and BuffTap.action.target=='party1')")
test('Group skipped player remains excluded',group+"BuffTap:SetBlessingPlayer({unit='party1'},'skip',false); refresh(); assert(not BuffTap.action or BuffTap.action.target~='party1')")
test('Group Salvation protection falls through to next choice',group+"BuffTap.db.buffs.bos=true; BuffTap.db.groupBlessingPriorities.WARRIOR={'bos','bom'}; BuffTap:SetBlessingPlayer({unit='party1'},nil,true); refresh(); assert(BuffTap.action.key=='bom' and BuffTap.action.target=='party1')")
test('Group raid exclusion overrides custom priorities',group+"BuffTap.db.raidGroups[1]=false; refresh(); assert(not BuffTap.action)")
test('Matching group fallback choices permit Greater',group+"classes.party2='WARRIOR'; BuffTap:InvalidateRoster(); refresh(); assert(BuffTap.action.key=='gbok' and BuffTap.action.groupCast)")
test('Mixed group fallback choices forbid Greater',group+"classes.party2='WARRIOR'; BuffTap:InvalidateRoster(); aura('party1',20217,'Blessing of Kings'); auras.party1[1].sourceUnit='other'; refresh(); assert(BuffTap.action and not BuffTap.action.groupCast)")
test('Unknown same-class member blocks Greater',group+"classes.party2='WARRIOR'; BuffTap:InvalidateRoster(); aura('party2',19740,'Blessing of Might'); refresh(); assert(BuffTap.action.key=='bok' and not BuffTap.action.groupCast)")
test('Changed group fallback cancels prepared Greater',group+"classes.party2='WARRIOR'; BuffTap:InvalidateRoster(); refresh(); assert(BuffTap.action.groupCast); aura('party1',20217,'Blessing of Kings'); auras.party1[1].sourceUnit='other'; BuffTap.button.scripts.PreClick(nil,'LeftButton'); assert(not BuffTap.action)")
test('Changed group ownership cancels prepared individual',group+"aura('party1',20217,'Blessing of Kings'); auras.party1[1].sourceUnit='other'; refresh(); assert(BuffTap.action.key=='bom'); auras.party1[1].sourceUnit='player'; BuffTap.button.scripts.PreClick(nil,'LeftButton'); assert(not BuffTap.action)")
test('Grouped friendly target uses group list not target list',group+"BuffTap.db.friendlyTarget=true; classes.target='WARRIOR'; UnitGUID=function(u) return 'Player-'..(u=='target' and 'party1' or u) end; BuffTap.db.targetBlessingClasses.WARRIOR='priority'; BuffTap.db.targetBlessingPriorities.WARRIOR={'bow'}; refresh(); assert(BuffTap.action.quickTarget and BuffTap.action.key=='bok' and BuffTap.action.blessingAssigned)")
test('Priority data sanitizes unknown duplicate and malformed entries',ordered+"BuffTap.db.targetBlessingPriorities={PRIEST={'bok','bok','invalid','bow'},INVALID={'bom'},DRUID=7}; BuffTap:InitDB(); assert(#BuffTap.db.targetBlessingPriorities.PRIEST==2 and BuffTap.db.targetBlessingPriorities.PRIEST[2]=='bow' and not BuffTap.db.targetBlessingPriorities.INVALID and not BuffTap.db.targetBlessingPriorities.DRUID)")
test('Target and group lists remain independent',ordered+"BuffTap.db.groupBlessingPriorities.PRIEST={'bom'}; refresh(); assert(BuffTap.action.key=='bok')")
test('Direct editor previews existing preference without saving',priority+"BuffTap:Options(); local f=BuffTap.options; local p=f.targetBlessingPicks[5]; p.scripts.OnClick(p); assert(BuffTap.db.targetBlessingClasses.PRIEST=='bok' and not BuffTap.db.targetBlessingPriorities.PRIEST and p.editorOrder[1]=='bok' and f.blessingMenu.priorityRows[1].shown)")
test('Editor reorder updates numbers and preserves popup',ordered+"BuffTap:Options(); local f=BuffTap.options; local p=f.targetBlessingPicks[5]; p.scripts.OnClick(p); local row=f.blessingMenu.priorityRows[2]; row.up.scripts.OnClick(row.up); assert(BuffTap.db.targetBlessingPriorities.PRIEST[1]=='bow' and f.blessingMenu.shown)")
test('Editor inclusion appends and exclusion removes without gaps',ordered+"BuffTap:Options(); local f=BuffTap.options; f.targetBlessingPicks[5].scripts.OnClick(f.targetBlessingPicks[5]); local row=f.blessingMenu.priorityRows[1]; row.toggle.scripts.OnClick(row.toggle); assert(#BuffTap.db.targetBlessingPriorities.PRIEST==3 and BuffTap.db.targetBlessingPriorities.PRIEST[1]=='bow'); row=f.blessingMenu.priorityRows[5]; row.toggle.scripts.OnClick(row.toggle); assert(#BuffTap.db.targetBlessingPriorities.PRIEST==4)")
test('Group editor writes only group priorities',group+"BuffTap:Options(); local f=BuffTap.options; local p=f.blessingRows[1].pick; p.scripts.OnClick(p); local row=f.blessingMenu.priorityRows[2]; row.up.scripts.OnClick(row.up); assert(BuffTap.db.groupBlessingPriorities.WARRIOR[1]=='bom' and not BuffTap.db.targetBlessingPriorities.WARRIOR)")
test('Same custom picker click closes expanded editor',ordered+"BuffTap:Options(); local f=BuffTap.options; local p=f.targetBlessingPicks[5]; p.scripts.OnClick(p); p.scripts.OnClick(p); assert(not f.blessingMenu.shown)")
test('Editor automatic restores defaults without deleting saved list',ordered+"BuffTap:Options(); local f=BuffTap.options; f.targetBlessingPicks[5].scripts.OnClick(f.targetBlessingPicks[5]); local b=f.blessingMenu.priorityAutomatic; b.scripts.OnClick(b); assert(not BuffTap.db.targetBlessingClasses.PRIEST and #BuffTap.db.targetBlessingPriorities.PRIEST==4)")
test('Editor cannot reorder in combat',ordered+"BuffTap:Options(); local f=BuffTap.options; f.targetBlessingPicks[5].scripts.OnClick(f.targetBlessingPicks[5]); combat=true; local b=f.blessingMenu.priorityRows[2].up; b.scripts.OnClick(b); assert(BuffTap.db.targetBlessingPriorities.PRIEST[1]=='bok')")
for cls in ['DRUID','HUNTER','MAGE','PALADIN','PRIEST','SHAMAN','WARLOCK','WARRIOR']:
 test('Visual ordering controls for '+cls,"playerClass='"+cls+"'; BuffTap:Options(); local f=BuffTap.options; local first=f.buffRows[1]; assert(first and not first.drag and first.up and first.down); local second=f.buffRows[2]; if second and second.shown then local key=second.def.key; second.up.scripts.OnClick(second.up); assert(f.buffRows[1].def.key==key and BuffTap.db.priorities[key]==1) else assert(not first.up.enabled and not first.down.enabled) end")
test('Rogue weapon choices do not gain a meaningless spell priority list',"playerClass='ROGUE'; BuffTap:Options(); assert(BuffTap.options.emptyBuffs.shown)")
test('No-overwrite policy schedules known coverage expiry',ordered+"BuffTap.db.targetBlessingPriorities.PRIEST={'bok'}; aura('target',20217,'Blessing of Kings'); auras.target[1].sourceUnit='other'; auras.target[1].duration=3600; auras.target[1].expirationTime=GetTime()+1000; refresh(); assert(not BuffTap.action.quickTarget and BuffTap.nextWakeDelay and BuffTap.nextWakeDelay<=700)")
test('Custom target lists support all five catalog blessings',ordered+"BuffTap.db.targetBlessingPriorities.PRIEST={'bok','bow','bol','bos','bom'}; BuffTap.db.buffs.bom=true; for _,a in ipairs({{20217,'Blessing of Kings'},{19742,'Blessing of Wisdom'},{19977,'Blessing of Light'},{1038,'Blessing of Salvation'}}) do aura('target',a[1],a[2]); auras.target[#auras.target].sourceUnit='other' end; refresh(); assert(BuffTap.action.key=='bom')")
test('Name-only blessing with unknown owner blocks fallback',ordered+"aura('target',20217,'Blessing of Kings'); auras.target[1].spellId=nil; refresh(); assert(not BuffTap.action.quickTarget)")
test('Unknown-owner group class cannot qualify for Greater',group+"classes.party2='WARRIOR'; BuffTap:InvalidateRoster(); aura('party2',20217,'Blessing of Kings'); refresh(); assert(BuffTap.action.key=='bok' and not BuffTap.action.groupCast)")
test('Priority editor closes with options',ordered+"BuffTap:Options(); local f=BuffTap.options; f.targetBlessingPicks[5].scripts.OnClick(f.targetBlessingPicks[5]); f:Hide(); assert(not f.blessingMenu.shown)")
test('Group custom mode is opt-in and preserves fixed selections',setup+"BuffTap:InitDB(); assert(BuffTap.db.blessingClasses.WARRIOR=='bom' and not next(BuffTap.db.groupBlessingPriorities))")
for locale in ['esES','deDE','frFR','ptBR']:
 test('Priority editor builds with translated controls '+locale,ordered+"BuffTap:Options(); local f=BuffTap.options; f.targetBlessingPicks[5].scripts.OnClick(f.targetBlessingPicks[5]); assert(f.blessingMenu.priorityHelp.text~= 'Check to include. Use arrows to order; 1 is first.')",locale=locale)
test('Own tactical blessing blocks target priority replacement',ordered+"aura('target',1044,'Blessing of Freedom'); auras.target[1].sourceUnit='player'; refresh(); assert(not BuffTap.action.quickTarget)")
test('Unknown tactical blessing blocks group priority replacement',group+"aura('party1',1022,'Blessing of Protection'); refresh(); assert(not BuffTap.action or BuffTap.action.target~='party1')")
test('Known other tactical blessing does not occupy own slot',ordered+"aura('target',6940,'Blessing of Sacrifice'); auras.target[1].sourceUnit='other'; refresh(); assert(BuffTap.action.key=='bok')")
test('Priority editor contains arrows without drag controls',ordered+"BuffTap:Options(); local f=BuffTap.options; f.targetBlessingPicks[5].scripts.OnClick(f.targetBlessingPicks[5]); for _,row in ipairs(f.blessingMenu.priorityRows) do assert(not row.drag and row.up and row.down) end")
test('Custom priorities have no second availability gate',ordered+"BuffTap.db.targetBuffs.bok=false; BuffTap.db.targetBuffs.bow=false; refresh(); assert(BuffTap.action.key=='bok')")
test('Class-aware Paladin page hides redundant spell section',ordered+"BuffTap:Options(); assert(not BuffTap.options.targetHeaders.shown and not BuffTap.options.targetScroll.shown)")
test('Non-Paladin target page retains necessary spell controls',"BuffTap:Options(); assert(BuffTap.options.targetHeaders.shown and BuffTap.options.targetScroll.shown)")
test('Disabling class-aware mode reveals legacy target controls',ordered+"BuffTap.db.targetClassBlessings=false; BuffTap:Options(); assert(BuffTap.options.targetHeaders.shown and BuffTap.options.targetScroll.shown)")
test('Custom target priorities use visible shared timing',ordered+"BuffTap.db.targetSeconds=420; BuffTap.db.targetBuffSeconds.bok=900; assert(BuffTap:TargetRebuffSeconds(BuffTap:FindBuff('bok'))==420)")
test('Group priority choice is enabled by its own checkbox',group+"BuffTap.db.buffs.bok=false; BuffTap.db.buffGroups.bok={[1]=false}; refresh(); assert(BuffTap.action.key=='bok')")
test('Automatic editor opens directly without committing previews',solo+"BuffTap:Options(); local f=BuffTap.options; local p=f.targetBlessingPicks[5]; p.scripts.OnClick(p); assert(f.blessingMenu.priorityRows[1].shown and not BuffTap.db.targetBlessingClasses.PRIEST and not BuffTap.db.targetBlessingPriorities.PRIEST); f.blessingMenu.priorityDone.scripts.OnClick(); assert(not BuffTap.db.targetBlessingClasses.PRIEST)")
test('First Automatic checkbox edit preserves preview order',solo+"BuffTap:Options(); local f=BuffTap.options; local p=f.targetBlessingPicks[5]; p.scripts.OnClick(p); local first=p.editorOrder[1]; local row=f.blessingMenu.priorityRows[3]; row.toggle.scripts.OnClick(row.toggle); assert(BuffTap.db.targetBlessingClasses.PRIEST=='priority' and BuffTap.db.targetBlessingPriorities.PRIEST[1]==first)")
test('Skipped class editor opens empty without unskipping',ordered+"BuffTap.db.targetBlessingClasses.PRIEST='skip'; BuffTap:Options(); local f=BuffTap.options; local p=f.targetBlessingPicks[5]; p.scripts.OnClick(p); assert(#p.editorOrder==0 and BuffTap.db.targetBlessingClasses.PRIEST=='skip')")
test('Missing saved custom list safely opens empty',ordered+"BuffTap.db.targetBlessingPriorities.PRIEST=nil; BuffTap:Options(); local f=BuffTap.options; local p=f.targetBlessingPicks[5]; p.scripts.OnClick(p); assert(#p.editorOrder==0 and #f.blessingMenu.priorityRows==5)")
test('Switching class editors does not copy another class list',group+"BuffTap:Options(); local f=BuffTap.options; local a=f.blessingRows[1].pick; local b=f.blessingRows[2].pick; a.scripts.OnClick(a); b.scripts.OnClick(b); assert(f.blessingMenu.owner==b and #b.editorOrder==0 and not BuffTap.db.groupBlessingPriorities.PALADIN)")
test('Group fixed choice remains fixed when editor closes',setup+"BuffTap:Options(); local f=BuffTap.options; f.blessingRows[1].pick.scripts.OnClick(f.blessingRows[1].pick); f.blessingMenu.priorityDone.scripts.OnClick(); refresh(); assert(BuffTap.db.blessingClasses.WARRIOR=='bom' and not BuffTap.db.groupBlessingPriorities.WARRIOR and BuffTap.action.key=='bom')")
print('ALL',len(tests),'SCENARIOS PASSED')
